/** Per-call limit, enforced by LiveKit when the room is created. */
export const MAX_CALL_PARTICIPANTS = 8;

/** Call room IDs are random strings generated by the browser. */
export const ROOM_ID_REGEX = /^[A-Za-z0-9_-]{16,64}$/;

export function newRoomId(): string {
  return crypto.randomUUID().replace(/-/g, "");
}
